import test from 'node:test';import assert from 'node:assert/strict';
import {bundleRouteSegments,bundledGeometry,roundedRoutePath} from '../src/ui/route-bundles.js';
import {armyArrowWidth} from '../src/ui/operation-geometry.js';
import {renderCampaignRoutes} from '../src/ui/campaign-routes.js';
import {campaign28Fixture} from './campaign-v28-fixture.mjs';
import {geometryFor} from '../src/model/cartography-geometry.js';
const route=(personId,path,extra={})=>({key:personId+path.join('-'),personId,path,fromId:path[0],toId:path.at(-1),countryId:'a',side:'attack',army:7,...extra});
test('separate origins join a thicker common trunk and split into distinct destinations',()=>{const routes=[route('a',['1','2','3','4']),route('b',['5','2','3','6'])],copy=JSON.stringify(routes),b=bundleRouteSegments(routes);assert.equal(b.length,5);const trunk=b.find(r=>r.fromId==='2'&&r.toId==='3');assert.equal(trunk.count,2);assert.equal(trunk.width,armyArrowWidth(7)*1.25);assert.equal(trunk.terminal,false);assert.deepEqual(b.filter(r=>r.terminal).map(r=>r.toId).sort(),['4','6']);assert(b.some(r=>r.path.join('>')==='1>2'));assert(b.some(r=>r.path.join('>')==='5>2'));assert.equal(JSON.stringify(routes),copy);});
test('only contiguous overlap merges; one commander repeatedly using a path is not counted as multiple units',()=>{const b=bundleRouteSegments([route('a',['1','2','3']),route('a',['1','2','3']),route('b',['4','2','3'])]),trunk=b.find(r=>r.path.join('>')==='2>3');assert.equal(trunk.count,2);assert.equal(trunk.people.size,2);});
test('countries, opposite directions, defensive movement, counterattack and retreat remain distinct',()=>{const b=bundleRouteSegments([route('a',['1','2']),route('b',['1','2'],{countryId:'b'}),route('c',['2','1']),route('d',['1','2'],{side:'defense'}),route('e',['1','2'],{side:'defense',counterattack:true}),route('f',['1','2'],{side:'retreat'})]);assert.equal(b.length,6);assert(b.every(r=>r.count===1));});
test('three shared units get1.5x width and shared thickness has a bounded maximum',()=>{for(const count of [3,4,10]){const r=bundleRouteSegments(Array.from({length:count},(_,i)=>route('p'+i,['1','2'],{army:21})))[0];assert.equal(r.width,armyArrowWidth(21)*Math.min(1.75,1+.25*(count-1)));}});
test('connected serial edges with the same participants form a single continuous trunk',()=>{const r=bundleRouteSegments([route('a',['1','2','3','4']),route('b',['1','2','3','4'])]);assert.equal(r.length,1);assert.deepEqual(r[0].path,['1','2','3','4']);assert(r[0].terminal);});
test('cycles do not hang or collapse into invisible zero-length routes',()=>{const r=bundleRouteSegments([route('a',['1','2']),route('a',['2','3']),route('a',['3','1'])]);assert(r.length>=2);assert(r.every(r=>r.fromId!==r.toId));});
test('a branch endpoint and trunk start use the identical junction coordinate, with opposite flows offset',()=>{const w=campaign28Fixture().world,ge=geometryFor(w),raw=[route('a',['tile-0','tile-1','tile-2','tile-3']),route('b',['tile-4','tile-1','tile-2','tile-5']),route('c',['tile-2','tile-1'],{countryId:'b'})],b=bundledGeometry(w,ge,bundleRouteSegments(raw)),branch=b.find(r=>r.fromId==='tile-0'),trunk=b.find(r=>r.fromId==='tile-1'&&r.toId==='tile-2');assert.deepEqual(branch.points.at(-1),trunk.points[0]);assert(trunk.points.length>2);const curve=roundedRoutePath(trunk.points);assert(curve.includes(' Q'));assert(!/NaN|Infinity/.test(curve));});
test('summary groups past routes, selected/moving officers stay individual, and full mode remains available',()=>{const w=campaign28Fixture().world,g=geometryFor(w),campaign={routes:[route('a0',['tile-0','tile-1','tile-2']),route('a1',['tile-3','tile-1','tile-2'])],fronts:[],movements:[]},snapshot=JSON.stringify(campaign),summary=renderCampaignRoutes(w,g,campaign,{routeMode:'summary'}),selected=renderCampaignRoutes(w,g,campaign,{routeMode:'summary',selectedPersonId:'a0'}),full=renderCampaignRoutes(w,g,campaign,{routeMode:'all'});assert(summary.includes('2개 부대'));assert(summary.includes('is-summary'));assert(selected.includes('data-route-person="a0"'));assert(!selected.includes('2개 부대'));assert(!full.includes('is-summary'));assert.equal(JSON.stringify(campaign),snapshot);});
